-- A4: size distribution of large columns (pg_column_size = on-disk incl. toast compression)
SELECT * FROM (
SELECT 'ai_request_payloads','request_body',count(*),pg_size_pretty(avg(pg_column_size(request_body))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(request_body))::bigint),pg_size_pretty(max(pg_column_size(request_body))::bigint),pg_size_pretty(sum(pg_column_size(request_body))::bigint) FROM ai_request_payloads
UNION ALL SELECT 'ai_request_payloads','response_body',count(*),pg_size_pretty(avg(pg_column_size(response_body))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(response_body))::bigint),pg_size_pretty(max(pg_column_size(response_body))::bigint),pg_size_pretty(sum(pg_column_size(response_body))::bigint) FROM ai_request_payloads
UNION ALL SELECT 'ai_request_payloads','offered_tools',count(*),pg_size_pretty(avg(pg_column_size(offered_tools))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(offered_tools))::bigint),pg_size_pretty(max(pg_column_size(offered_tools))::bigint),pg_size_pretty(sum(pg_column_size(offered_tools))::bigint) FROM ai_request_payloads
UNION ALL SELECT 'ai_request_payloads','prepared_tools',count(*),pg_size_pretty(avg(pg_column_size(prepared_tools))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(prepared_tools))::bigint),pg_size_pretty(max(pg_column_size(prepared_tools))::bigint),pg_size_pretty(sum(pg_column_size(prepared_tools))::bigint) FROM ai_request_payloads
UNION ALL SELECT 'ai_request_messages','content',count(*),pg_size_pretty(avg(pg_column_size(content))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(content))::bigint),pg_size_pretty(max(pg_column_size(content))::bigint),pg_size_pretty(sum(pg_column_size(content))::bigint) FROM ai_request_messages
UNION ALL SELECT 'event_outbox','fact',count(*),pg_size_pretty(avg(pg_column_size(fact))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(fact))::bigint),pg_size_pretty(max(pg_column_size(fact))::bigint),pg_size_pretty(sum(pg_column_size(fact))::bigint) FROM event_outbox
UNION ALL SELECT 'event_outbox','payload',count(*),pg_size_pretty(avg(pg_column_size(payload))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(payload))::bigint),pg_size_pretty(max(pg_column_size(payload))::bigint),pg_size_pretty(sum(pg_column_size(payload))::bigint) FROM event_outbox
UNION ALL SELECT 'logs','metadata',count(*),pg_size_pretty(avg(pg_column_size(metadata))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(metadata))::bigint),pg_size_pretty(max(pg_column_size(metadata))::bigint),pg_size_pretty(sum(pg_column_size(metadata))::bigint) FROM logs
UNION ALL SELECT 'logs','message',count(*),pg_size_pretty(avg(pg_column_size(message))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(message))::bigint),pg_size_pretty(max(pg_column_size(message))::bigint),pg_size_pretty(sum(pg_column_size(message))::bigint) FROM logs
UNION ALL SELECT 'governance_decisions','evaluated_rules',count(*),pg_size_pretty(avg(pg_column_size(evaluated_rules))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(evaluated_rules))::bigint),pg_size_pretty(max(pg_column_size(evaluated_rules))::bigint),pg_size_pretty(sum(pg_column_size(evaluated_rules))::bigint) FROM governance_decisions
UNION ALL SELECT 'governance_decisions','act_chain',count(*),pg_size_pretty(avg(pg_column_size(act_chain))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(act_chain))::bigint),pg_size_pretty(max(pg_column_size(act_chain))::bigint),pg_size_pretty(sum(pg_column_size(act_chain))::bigint) FROM governance_decisions
UNION ALL SELECT 'mcp_artifacts','data',count(*),pg_size_pretty(avg(pg_column_size(data))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(data))::bigint),pg_size_pretty(max(pg_column_size(data))::bigint),pg_size_pretty(sum(pg_column_size(data))::bigint) FROM mcp_artifacts
UNION ALL SELECT 'artifact_payloads','body',count(*),pg_size_pretty(avg(pg_column_size(body))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(body))::bigint),pg_size_pretty(max(pg_column_size(body))::bigint),pg_size_pretty(sum(pg_column_size(body))::bigint) FROM artifact_payloads
UNION ALL SELECT 'mcp_tool_executions','output',count(*),pg_size_pretty(avg(pg_column_size(output))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(output))::bigint),pg_size_pretty(max(pg_column_size(output))::bigint),pg_size_pretty(sum(pg_column_size(output))::bigint) FROM mcp_tool_executions
UNION ALL SELECT 'feedback_ingestion_evidence','evidence',count(*),pg_size_pretty(avg(pg_column_size(evidence))::bigint),pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY pg_column_size(evidence))::bigint),pg_size_pretty(max(pg_column_size(evidence))::bigint),pg_size_pretty(sum(pg_column_size(evidence))::bigint) FROM feedback_ingestion_evidence
) x;
-- raw (uncompressed) json text length for the two biggest
SELECT pg_size_pretty(avg(length(request_body::text))::bigint) req_raw_avg, pg_size_pretty(max(length(request_body::text))::bigint) req_raw_max,
       pg_size_pretty(avg(length(response_body::text))::bigint) resp_raw_avg, pg_size_pretty(avg(length(offered_tools::text))::bigint) tools_raw_avg
FROM ai_request_payloads;
-- how much of request_body is the tools array vs messages?
SELECT pg_size_pretty(avg(length((request_body->'tools')::text))::bigint) tools_in_body_avg, pg_size_pretty(avg(length((request_body->'messages')::text))::bigint) msgs_in_body_avg, pg_size_pretty(avg(length((request_body->'system')::text))::bigint) system_avg,
       avg(jsonb_array_length(request_body->'tools')) n_tools_avg, avg(jsonb_array_length(request_body->'messages')) n_msgs_avg
FROM ai_request_payloads WHERE jsonb_typeof(request_body->'tools')='array' AND jsonb_typeof(request_body->'messages')='array';
